def controls(source):
    marker = "theorem render_prepend"
    point = "ok (current, fun replacement => .occupied front key replacement suffix)"
    if source.count(marker) != 1 or source[:source.index(marker)].count(point) != 1:
        raise ValueError("CollectionsGapMutationPoint")
    mutant = source[:source.index(marker)].replace(point, "ok (current, fun replacement => .occupied (append front suffix) key replacement .nil)")
    mutant += """
example :
    (do let (_, backward) ← orDefault (fun _ => ok (0 : Nat))
          (Entry.vacant (.cons (1 : Nat) (10 : Nat) .nil) 2 (.cons 3 30 .nil));
        ok (keys (toMap (backward 20)))) = ok [1, 2, 3] := by
  simp [orDefault, toMap, append, keys]
end Correspondence036.CollectionsGap
"""
    return [("wrong-captured-gap", mutant, "normalized-False")]
